class Solution {
    unordered_map<string, string> parent;

    string root(const string& s) {
        if (!parent.count(s)) {
            parent[s] = s;
        }
        if (parent[s] != s) {
            parent[s] = root(parent[s]);
        }
        return parent[s];
    }

public:
    vector<string> generateSentences(vector<vector<string>>& synonyms,
                                     string text) {
        parent.clear();
        for (const auto& pair : synonyms) {
            string a = root(pair[0]);
            string b = root(pair[1]);
            parent[a] = b;
        }
        map<string, vector<string>> groups;
        for (const auto& item : parent) {
            groups[root(item.first)].push_back(item.first);
        }
        for (auto& item : groups) {
            sort(item.second.begin(), item.second.end());
        }
        vector<string> words;
        stringstream ss(text);
        string word;
        while (ss >> word) {
            words.push_back(word);
        }
        vector<string> answer;
        function<void(int, string)> dfs = [&](int i, string sentence) {
            if (i == static_cast<int>(words.size())) {
                answer.push_back(sentence);
                return;
            }
            string key = root(words[i]);
            vector<string> choices = groups.count(key) ? groups[key]
                                                      : vector<string>{words[i]};
            for (const string& choice : choices) {
                dfs(i + 1, sentence + (i == 0 ? "" : " ") + choice);
            }
        };
        dfs(0, "");
        sort(answer.begin(), answer.end());
        return answer;
    }
};
